"""Webhook signing secrets (D53): generated by Sibyl, shown once, sealed at rest.

The secret is ``whsec_`` + 32 random bytes (base64url, unpadded). It is sealed with
``seal_credential`` under the tenant ``credential`` DEK, AAD bound to the webhook's
``credential_id``, and read back only through ``sibyl.monitor_webhook_secret()`` (neither the api
nor the worker can SELECT the ciphertext). It is opened just before signing and never logged,
audited or returned after creation.
"""

from __future__ import annotations

import base64
import secrets
from typing import Any
from uuid import UUID

from sibyl_schemas.webhook_signature import SECRET_PREFIX

from ...core.crypto.deks import ConnDekProvider, DekUnavailable
from ...core.crypto.envelope import DecryptionError, EncryptedBlob, KeyEncryptionKey
from ...core.crypto.sealed import open_credential, seal_credential

SECRET_BYTES = 32
_SECRET_SQL = "SELECT * FROM sibyl.monitor_webhook_secret($1)"  # noqa: S105 (SQL, not a secret)


class SecretUnavailable(Exception):
    """The secret is missing or cannot be opened (shredded tenant key, wrong AAD)."""


def new_secret() -> str:
    raw = base64.urlsafe_b64encode(secrets.token_bytes(SECRET_BYTES)).rstrip(b"=").decode()
    return SECRET_PREFIX + raw


async def seal_secret(
    conn: Any, kek: KeyEncryptionKey, tenant: UUID, credential_id: UUID, secret: str
) -> tuple[EncryptedBlob, UUID]:
    sealed = await seal_credential(
        ConnDekProvider(conn, kek), tenant, credential_id, secret.encode("ascii")
    )
    return sealed.blob, sealed.key_id


async def open_secret(conn: Any, kek: KeyEncryptionKey, tenant: UUID, webhook_id: UUID) -> str:
    row = await conn.fetchrow(_SECRET_SQL, webhook_id)
    if row is None:
        raise SecretUnavailable("no webhook secret")
    blob = EncryptedBlob(int(row["key_version"]), bytes(row["nonce"]), bytes(row["ciphertext"]))
    try:
        secret = await open_credential(
            ConnDekProvider(conn, kek), tenant, row["credential_id"], blob
        )
    except (DekUnavailable, DecryptionError):
        raise SecretUnavailable("the webhook secret cannot be opened") from None
    return secret.decode("ascii")
